edits.oldText:
export function apiRateLimit(enabled: boolean) {
  if (!enabled) {
    return { limit: 0, reason: "Disabled" };
  }
  return { limit: 100 };
}

edits.newText:
export function apiRateLimit(enabled: boolean) {
  if (!enabled) {
    return { limit: 0, reason: "API limit disabled" };
  }
  return { limit: 100 };
}
